    wire [3:0] bgo = {bco3[0], bco2[0], bco1[0], bco0[0]};
    always @(negedge ck) begin
        for (c = 0; c < 4; c = c + 1)
            if (bgo[c] === 1'b1) begin
                if (bseen[c] >= NOPS || cyc != t_go[bseen[c]] + Q3H_LAT_BCO) begin
                    $display("FAIL bco%0d go at cycle %0d", c, cyc); errors = errors + 1;
                end
                bseen[c] = bseen[c] + 1;
            end
        if (rs[512] === 1'b1) begin
            if (rseen >= NOPS) begin $display("FAIL extra rs word at cycle %0d", cyc); errors = errors + 1; end
            else begin
                $display("RS op %0d cycle %0d latency %0d (compiled %0d) fault %b match %0d", rseen, cyc, cyc - t_go[rseen], LAT_RS, rs[513], rs[511:0] === gold[rseen]);
                if (cyc != t_go[rseen] + LAT_RS) begin $display("FAIL rs latency"); errors = errors + 1; end
                if (rs[513] !== 1'b0) begin $display("FAIL rs fault bit"); errors = errors + 1; end
                if (rs[511:0] !== gold[rseen]) begin $display("FAIL rs data op %0d: %h expected %h", rseen, rs[511:0], gold[rseen]); errors = errors + 1; end
            end
            rseen = rseen + 1;
        end
        if (cyc == t_go[NOPS-1] + LAT_RS + 60) begin
            if (rseen != NOPS) begin $display("FAIL saw %0d rs words, expected %0d", rseen, NOPS); errors = errors + 1; end
            for (c = 0; c < 4; c = c + 1) if (bseen[c] != NOPS) begin $display("FAIL bco%0d saw %0d gos", c, bseen[c]); errors = errors + 1; end
            errors = errors + (u_f_0_0.gseen != NOPS) + (u_f_0_1.gseen != NOPS) + (u_f_0_2.gseen != NOPS) + (u_f_0_3.gseen != NOPS) + (u_f_1_0.gseen != NOPS) + (u_f_1_1.gseen != NOPS) + (u_f_1_2.gseen != NOPS) + (u_f_1_3.gseen != NOPS) + (u_f_2_0.gseen != NOPS) + (u_f_2_1.gseen != NOPS) + (u_f_2_2.gseen != NOPS) + (u_f_2_3.gseen != NOPS) + (u_f_3_0.gseen != NOPS) + (u_f_3_1.gseen != NOPS) + (u_f_3_2.gseen != NOPS) + (u_f_3_3.gseen != NOPS);
            if (errors == 0) $display("Q3H_REGIONAL_FABRIC_PASS MUT %0d FAR %0d ops %0d tap %0d/%0d/%0d/%0d bco %0d rs %0d", MUT, far, NOPS, Q3H_LAT_TAP0, Q3H_LAT_TAP1, Q3H_LAT_TAP2, Q3H_LAT_TAP3, Q3H_LAT_BCO, LAT_RS);
            else $display("Q3H_CB16_FAIL MUT %0d FAR %0d errors %0d", MUT, far, errors);
            $finish;
        end
    end
